import{_ as i,o,c as a,ae as t}from"./chunks/framework.B3uLoxsb.js";const m=JSON.parse('{"title":"Source: docs/COMPARISON.md","description":"","frontmatter":{},"headers":[],"relativePath":"pt/reference/source/comparison.md","filePath":"pt/reference/source/comparison.md","lastUpdated":1771052491000}'),l={name:"pt/reference/source/comparison.md"};function r(s,e,c,n,d,p){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="source-docs-comparison-md" tabindex="-1">Source: docs/COMPARISON.md <a class="header-anchor" href="#source-docs-comparison-md" aria-label="Permalink to &quot;Source: docs/COMPARISON.md&quot;">​</a></h1><h1 id="comparison-external-baseline-vs-codex-workflows" tabindex="-1">Comparison: External Baseline vs Codex Workflows <a class="header-anchor" href="#comparison-external-baseline-vs-codex-workflows" aria-label="Permalink to &quot;Comparison: External Baseline vs Codex Workflows&quot;">​</a></h1><p>Date: 2026-02-13</p><h2 id="source-baseline" tabindex="-1">Source baseline <a class="header-anchor" href="#source-baseline" aria-label="Permalink to &quot;Source baseline&quot;">​</a></h2><p>The external baseline README describes a broad toolkit with:</p><ul><li>20 specialized agents</li><li>36 skills</li><li>11 workflows</li></ul><p>Codex Workflows is adapted to Codex skill mechanics and repository-local <code>.agent</code> integration.</p><h2 id="what-the-external-baseline-does-strongly" tabindex="-1">What the external baseline does strongly <a class="header-anchor" href="#what-the-external-baseline-does-strongly" aria-label="Permalink to &quot;What the external baseline does strongly&quot;">​</a></h2><ul><li>Rich specialist catalog (agents, skills, workflows)</li><li>Strong orchestration concepts</li><li>Command-driven workflow style</li><li>Large knowledge surface for many domains</li></ul><h2 id="previous-gap-in-this-repository" tabindex="-1">Previous gap in this repository <a class="header-anchor" href="#previous-gap-in-this-repository" aria-label="Permalink to &quot;Previous gap in this repository&quot;">​</a></h2><p>Before this refactor, <code>codex-workflows</code> had:</p><ul><li>1 skill</li><li>1 compact playbook file</li><li>no automation scripts</li><li>no local template scaffolding</li></ul><h2 id="refactor-outcomes-in-this-repository" tabindex="-1">Refactor outcomes in this repository <a class="header-anchor" href="#refactor-outcomes-in-this-repository" aria-label="Permalink to &quot;Refactor outcomes in this repository&quot;">​</a></h2><p>Now includes:</p><ul><li>structured per-workflow references</li><li>routing matrix and orchestration gates</li><li>deterministic and fast router variants</li><li>local <code>.agent</code> bootstrap script</li><li>reusable <code>.agent</code> template bundle</li><li>compatibility manifest and drift checks</li><li>workflow parity checks</li><li>CI validation and unit tests</li><li>codex-native domain packs (backend/frontend/security/qa)</li><li>explicit architecture docs</li></ul><h2 id="practical-difference-now" tabindex="-1">Practical difference now <a class="header-anchor" href="#practical-difference-now" aria-label="Permalink to &quot;Practical difference now&quot;">​</a></h2><p>Benchmark-level robustness is approximated by combining:</p><ul><li>a strong router skill</li><li>codified workflow knowledge base</li><li>automation scripts</li><li>project-level template scaffolding</li><li>full compatibility pack mirroring <code>.agent</code> structure (<code>packs/antigravity-compat/.agent</code>)</li><li>scriptable sync path for future updates (<code>scripts/sync_compat_pack.py</code>)</li></ul><p>This keeps compatibility with Codex while preserving the workflow mindset.</p><h2 id="codex-native-default-track" tabindex="-1">Codex-native default track <a class="header-anchor" href="#codex-native-default-track" aria-label="Permalink to &quot;Codex-native default track&quot;">​</a></h2><p>Bootstrap now defaults to:</p><p><code>bootstrap_project_agent.py --profile codex-native</code></p><p>This profile boots from an independent codex-native template root:</p><ul><li><code>skills/codex-workflows/templates/codex-native/.agent</code></li><li>with all 13 rewritten workflow definitions in <code>workflows/*.md</code></li><li>with native specialist agents in <code>agents/*.md</code></li><li>with native capability skills in <code>skills/*/SKILL.md</code></li><li><code>antigravity-compat</code> remains opt-in interoperability mode.</li></ul><p>Quality is enforced by:</p><ul><li><code>skills/codex-workflows/scripts/check_codex_native_quality.py</code></li><li><code>skills/codex-workflows/scripts/check_codex_native_assets.py</code></li><li>CI execution in <code>.github/workflows/ci.yml</code></li><li>similarity threshold guard (<code>--max-similarity 0.35</code>) versus compatibility workflows.</li></ul><p>References are now codex-native aligned:</p><ul><li><code>skills/codex-workflows/references/workflows/*.md</code></li><li>byte-parity with <code>templates/codex-native/.agent/workflows/*.md</code></li><li>explicitly separated from compatibility parity checks.</li></ul><h2 id="compatibility-mode" tabindex="-1">Compatibility Mode <a class="header-anchor" href="#compatibility-mode" aria-label="Permalink to &quot;Compatibility Mode&quot;">​</a></h2><p>For near-equivalent structure to external benchmark projects, bootstrap with:</p><p><code>bootstrap_project_agent.py --profile antigravity-compat</code></p><p>This installs a complete <code>.agent</code> tree including agents, skills, workflows, rules, scripts, and shared assets.</p><p>Compatibility parity is maintained between:</p><ul><li><code>skills/codex-workflows/templates/.agent/workflows/*.md</code></li><li><code>skills/codex-workflows/packs/antigravity-compat/.agent/workflows/*.md</code></li></ul><h2 id="remaining-expansion-path" tabindex="-1">Remaining expansion path <a class="header-anchor" href="#remaining-expansion-path" aria-label="Permalink to &quot;Remaining expansion path&quot;">​</a></h2><ol><li>Expand codex-native workflow depth with stack-specific execution branches.</li><li>Add benchmark thresholds and trend tracking for routing/bootstrap latency.</li><li>Add broader end-to-end sample implementations with automated golden checks.</li></ol>',36)])])}const u=i(l,[["render",r]]);export{m as __pageData,u as default};
